<?php
declare(strict_types=1);namespace App\Http\Controllers\Finance;use App\Http\Controllers\Controller;use App\Http\Requests\Finance\InvoiceRequest;use App\Models\{AcademicYear,Classroom,Semester,Student};use App\Models\Finance\{FeeType,StudentInvoice};use App\Services\Finance\InvoiceService;use Illuminate\Http\Request;
class StudentInvoiceController extends Controller{private function options():array{return ['students'=>Student::orderBy('full_name')->get(),'years'=>AcademicYear::latest('starts_at')->get(),'semesters'=>Semester::latest('starts_at')->get(),'feeTypes'=>FeeType::where('active',true)->orderBy('name')->get(),'classrooms'=>Classroom::with('gradeLevel')->orderBy('code')->get()];}public function index(Request $r){$q=StudentInvoice::with(['student.activeClassroomMembership.classroom','items.feeType']);foreach(['academic_year_id','semester_id','status','student_id'] as $f)if($r->filled($f))$q->where($f,$r->$f);if($r->filled('month'))$q->whereMonth('billing_month',$r->month);if($r->filled('fee_type_id'))$q->whereHas('items',fn($x)=>$x->where('fee_type_id',$r->fee_type_id));if($r->filled('classroom_id'))$q->whereHas('student.activeClassroomMembership',fn($x)=>$x->where('classroom_id',$r->classroom_id));if($r->filled('search'))$q->whereHas('student',fn($x)=>$x->where(fn($y)=>$y->where('full_name','like','%'.$r->search.'%')->orWhere('nis','like','%'.$r->search.'%')->orWhere('nisn','like','%'.$r->search.'%')));return view('finance.invoices.index',['invoices'=>$q->latest('issue_date')->paginate(20)->withQueryString()]+$this->options());}public function create(){return view('finance.invoices.form',['invoice'=>new StudentInvoice]+$this->options());}public function store(InvoiceRequest $r,InvoiceService $s){$i=$s->save($r->validated(),null,$r->user()->id);return redirect()->route('finance.invoices.show',$i)->with('success','Tagihan berhasil dibuat.');}public function show(StudentInvoice $invoice){return view('finance.invoices.show',['invoice'=>$invoice->load(['student.activeClassroomMembership.classroom','items.feeType','payments'])]);}public function edit(StudentInvoice $invoice){abort_if(in_array($invoice->status,['paid','cancelled'],true),422);return view('finance.invoices.form',['invoice'=>$invoice]+$this->options());}public function update(InvoiceRequest $r,StudentInvoice $invoice,InvoiceService $s){$s->save($r->validated(),$invoice,$r->user()->id);return redirect()->route('finance.invoices.show',$invoice)->with('success','Tagihan diperbarui.');}public function cancel(Request $r,StudentInvoice $invoice,InvoiceService $s){abort_unless($r->user()->can('finance.invoice.cancel'),403);$s->cancel($invoice,$r->user()->id);return back()->with('success','Tagihan dibatalkan.');}}
